#define _GNU_SOURCE
#include <malloc.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <unistd.h>

static int listener = -1;
static void *observe(void *unused) {
    (void)unused;
    for (;;) {
        int client = accept(listener, NULL, NULL);
        if (client < 0) break;
        FILE *output = fdopen(client, "w");
        if (!output) { close(client); continue; }
        struct mallinfo2 info = mallinfo2();
        fprintf(output, "%ld %zu %zu %zu %zu %zu %zu %zu %zu %zu %zu\n",
            (long)getpid(), info.arena, info.ordblks, info.smblks, info.hblks,
            info.hblkhd, info.usmblks, info.fsmblks, info.uordblks,
            info.fordblks, info.keepcost);
        if (malloc_info(0, output) != 0) fputs("OBSERVER_ERROR\n", output);
        fclose(output);
    }
    return NULL;
}
__attribute__((constructor)) static void start_observer(void) {
    const char *path = getenv("RELAY_ALLOCATOR_SOCKET");
    if (!path) return;
    const char *expected = getenv("RELAY_ALLOCATOR_EXE");
    char *executable = realpath("/proc/self/exe", NULL);
    int same_executable = expected && executable && strcmp(expected, executable) == 0;
    free(executable);
    if (!same_executable) return;
    FILE *arguments = fopen("/proc/self/cmdline", "rb");
    if (!arguments) return;
    char *argument = NULL; size_t capacity = 0; int bound = 0;
    while (getdelim(&argument, &capacity, '\0', arguments) >= 0) {
        if (strcmp(argument, "--bind") == 0) bound = 1;
    }
    free(argument); fclose(arguments);
    if (!bound) return;
    struct sockaddr_un address = { .sun_family = AF_UNIX };
    if (strlen(path) >= sizeof(address.sun_path)) { fputs("observer path exceeds AF_UNIX limit\n", stderr); return; }
    memcpy(address.sun_path, path, strlen(path) + 1);
    listener = socket(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0);
    if (listener < 0 || bind(listener, (struct sockaddr *)&address, sizeof(address)) != 0 || listen(listener, SOMAXCONN) != 0) {
        perror("observer socket"); if (listener >= 0) close(listener); return;
    }
    pthread_t thread;
    int error = pthread_create(&thread, NULL, observe, NULL);
    if (error != 0) { fprintf(stderr, "observer thread error %d\n", error); close(listener); return; }
    pthread_detach(thread);
}

